InstrumentGui *igui;

/* Task 8: the current preset-name node. Set on every graph build
 * (createPresetNameGuiNode). The SAVE action button uses it to commit
 * the instrument under the name currently shown. */
static PresetNameGuiNode *g_presetNameNode;


/* Task 9: preset-load-list state. g_loadList is populated by guiOpenLoadList
 * by enumerating data/instrument_presets/ .ipb files, stripping the
 * extension, and sorting alphabetically. While g_loadListActive is true,
 * handlePresetUiInput routes UP/DOWN/START/SELECT to the load-list node
 * regardless of which node is selected in the instrument graph. */
#define LOADLIST_MAX 256
#define LOADLIST_NAME_MAX 32
typedef struct {
	char names[LOADLIST_MAX][LOADLIST_NAME_MAX];
	int count;
	int highlight;
} PresetLoadList;

void createInstrumentGui(VoiceManager *vm, int *selectedInstrument, int scene) {
	InstrumentGui *ig = (InstrumentGui *)malloc(sizeof(InstrumentGui));
	if(!ig) return;
	memset(ig, 0, sizeof(InstrumentGui));
	ig->vm = vm;
	ig->selectedInstrument = selectedInstrument;

	for(int i = 0; i < vm->enabledChannels; i++) {
		bool isSelected = *selectedInstrument == i;
		ig->instrumentScreenGraphs[i] = createInstGraph(vm->instruments[i], vm, i, isSelected);
		ig->instrumentCount++;
	}
	/* Task 7: initialise the overlay layer stack. The stack starts empty;
	 * modals push layers on demand, the instrument input/draw path drains
	 * it when empty. */
	initLayerStack(&ig->overlayLayers);
	igui = ig;
}


/* selectedInstrument is a caller-owned int*, written by several paths (the
 * load list, the modal callbacks, channel-switch gestures). Both arrays
 * below are fixed at MAX_SEQUENCER_CHANNELS and both were indexed with it
 * unchecked, so an out-of-range selection returned whatever followed the
 * array in the struct — for instrumentScreenGraphs that is instrumentCount
 * reinterpreted as a Graph*, which the caller then dereferences. Clamp to the
 * array rather than reject: the caller asked for "the selected channel's
 * graph", and a clamped answer is a real object where NULL would force every
 * caller to grow a guard (TESTING.md I39). */
static int clampSelectedInstrument(void) {
	if(!igui || !igui->selectedInstrument) {
		return 0;
	}
	int i = *igui->selectedInstrument;
	if(i < 0) {
		return 0;
	}
	if(i >= MAX_SEQUENCER_CHANNELS) {
		return MAX_SEQUENCER_CHANNELS - 1;
	}
	return i;
}

/* Paired with createInstrumentGui. The instrument graphs own render textures
 * (each mod strip allocates a ping/pong pair), and those are released through
 * the mod-strip node's own destructor, so freeGuiNode on each root is enough.
 * Without this the GUI leaked on every rebuild -- valgrind found it while
 * testing the module (TESTING.md I40).
 *
 * The overlay stack is destroyed too: it holds the modal layers (the
 * route picker, the modulation screen), and destroyLayerStack frees each
 * layer's graph and name along with the stack's own array. Without it the
 * stack's array leaked on every teardown -- valgrind found it while
 * testing the modulation screen.
 *
 * Note the VoiceManager is *not* touched: it is process-lifetime state, and
 * gui_inst_mod.c's g_sourceCtx[] keeps Instrument pointers into it. */
void freeInstrumentGui(void) {
	if(!igui) {
		return;
	}
	for(int i = 0; i < MAX_SEQUENCER_CHANNELS; i++) {
		Graph *g = igui->instrumentScreenGraphs[i];
		if(g) {
			freeGuiNode(g->root);
			free(g);
			igui->instrumentScreenGraphs[i] = NULL;
		}
	}
	destroyLayerStack(&igui->overlayLayers);
	free(igui);
	igui = NULL;
}

Graph *getSelectedInstGraph() {
	if(!igui) {
		return NULL;
	}
	return igui->instrumentScreenGraphs[clampSelectedInstrument()];
}



InstrumentGui *getInstrumentGui(void) {
	return igui;
}

bool instrumentLayerModalActive(void) {
	if(!igui) {
		return false;
	}
	for(int i = igui->overlayLayers.count - 1; i >= 0; i--) {
		if(!igui->overlayLayers.layers[i].passive) {
			return true;
		}
	}
	return false;
}





